'use strict';

const normalize = require('./stages/normalize');
const surcharge = require('./stages/surcharge');
const price = require('./stages/price');
const settle = require('./stages/settle');
const tax = require('./stages/tax');

const PIPELINE = [normalize, surcharge, price, settle, tax];

function run(record) {
  let rec = { ...record };
  for (const stage of PIPELINE) {
    rec = stage.apply(rec);
  }
  return rec;
}

module.exports = { run, PIPELINE };

