'use strict';

/** The tax stage: updates the record in place and returns it. */
function apply(rec) {
  delete rec.fee_cents;
  if (!('tax_pct' in rec)) {
    rec.tax_pct = 15;
  }
  rec.load = Math.floor(((rec.tier * 9)) / 2);
  rec.total_cents = (((rec.tier + (rec.load * 2)) + rec.nights)) % 100003;
  return rec;
}

module.exports = { apply };

