'use strict';

const bundle = require('./stages/bundle');
const enrich = require('./stages/enrich');
const discount = require('./stages/discount');
const finalize = require('./stages/finalize');
const surcharge = require('./stages/surcharge');
const tax = require('./stages/tax');
const audit = require('./stages/audit');
const settle = require('./stages/settle');
const round_off = require('./stages/round_off');

const PIPELINE = [bundle, enrich, discount, finalize, surcharge, tax, audit, settle, round_off];

function run(record) {
  let rec = { ...record };
  for (const stage of PIPELINE) {
    rec = stage.apply(rec);
  }
  return rec;
}

module.exports = { run, PIPELINE };

